INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_ILLYRIAN','Illyrian (Iron Age to Roman attestation)',-800,300)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_WILKES_ILLYRIANS','secondary scholarship','John J. Wilkes, The Illyrians (Blackwell, 1992)','Illyrian peoples, history, religion and epigraphic record of the western Balkans'),
 ('SRC_STIPCEVIC_ILLYRIANS','secondary scholarship','Aleksandar Stipcevic, The Illyrians: History and Culture (Noyes Press, 1977)','Illyrian archaeology, cult, deities and religious iconography')
INSERT INTO _e VALUES
 ('ENT_ILL_PANTHEON','Illyrian Pantheon','collective','collective','Illyrian','polytheistic pantheon','B','Hub collective for the deities of the western-Balkan Illyrian peoples, attested chiefly through Latin votive inscriptions of the Roman period.'),
 ('ENT_ILL_MEDAURUS','Medaurus','deity','deity','Illyrian','war, horsemanship, civic protection','B','Great rider-god and tutelary deity of Risinium (Risan), depicted as a mounted lancer; attested in inscriptions and a dedication from Lambaesis honoring the god of Risinium.'),
 ('ENT_ILL_REDON','Redon','deity','deity','Illyrian','sea, travel, harbours','B','Tutelary sea and travel god of Lissus (Lezhe); attested on coins of Lissus and votive inscriptions, also found at Santa Maria di Leuca.'),
 ('ENT_ILL_BINDUS','Bindus','deity','deity','Illyrian','water, springs','B','Water-god of the Iapodes, worshipped at the spring of Privilica near Bihac; attested in Latin inscriptions as Bindus Neptunus, equated with Neptune.'),
 ('ENT_ILL_TADENUS','Tadenus','deity','deity','Illyrian','healing, springs','C','Local Dalmatian deity attested by inscriptions near the source of the Bosna river; sometimes associated with Apollo, of uncertain function (likely healing/spring).'),
 ('ENT_ILL_VIDASUS','Vidasus','deity','deity','Illyrian','forests, wild nature','B','Illyrian forest/woodland god attested at Topusko in Pannonia, regularly paired with the goddess Thana and identified with the Roman Silvanus.'),
 ('ENT_ILL_THANA','Thana','deity','deity','Illyrian','hunt, wild nature','B','Illyrian goddess of the hunt and woodland, consort of Vidasus at Topusko, identified with the Roman Diana.'),
 ('ENT_ILL_EIA','Eia','deity','deity','Illyrian','local tutelary, fertility (uncertain)','C','Illyrian goddess attested in inscriptions of the Histrian/north-Adriatic region (e.g. at Nesactium and Pola); function uncertain, likely a local tutelary/protective goddess.'),
 ('ENT_ILL_EN','En (Enji)','deity','deity','Illyrian','fire','C','Reconstructed Illyrian fire-god proposed as the source of the Albanian weekday e enjte (Thursday); inferred from linguistic/comparative evidence rather than direct inscription.'),
 ('ENT_ILL_DEIPATUROS','Dei-Paturos','deity','deity','Illyrian','sky, father-god','C','Illyrian-Thracian sky/father deity (name cognate with Indo-European *Dyeus-pater), attested for the Bessoi/Thracian-Illyrian borderlands; sometimes counted among Illyrian deities.'),
 ('ENT_ILL_SENTONA','Sentona','deity','deity','Illyrian','travel, roads, wellbeing','C','Illyrian (Liburnian/Histrian) goddess attested in votive inscriptions of the north-eastern Adriatic, possibly a goddess of travel/health; often paired in cult with Eia.'),
 ('ENT_ILL_ANZOTICA','Anzotica','deity','deity','Illyrian','love, beauty','C','Liburnian goddess worshipped at Aenona (Nin), identified with Venus in local inscriptions and statuary.');
